#include "engine.hpp"
#include <algorithm>
#include <cmath>
namespace uaa {
bool Engine::tradeAirport(std::size_t base,double at)const{if(base>=state["bases"].size())return false;bool runway=false,storage=false;for(const auto& b:state["bases"][base]["buildings"])if(b["ready"].get<double>()<=at&&b.value("floor",0)==0){runway|=b["id"]=="runway";storage|=b["id"]=="storage";}return runway&&storage;}
Json Engine::tradePartners()const{return constants["tradePartners"]["partners"];}
double Engine::tradeFlightHours(const std::string& partner,std::size_t base)const{if(base>=state["bases"].size())return 0;for(const auto& p:tradePartners())if(p["id"]==partner)return 2+std::ceil(distance(state["bases"][base]["lat"],state["bases"][base]["lon"],p["lat"],p["lon"])/700.);return 0;}
Result Engine::trade(const std::string& group,const std::string& id,bool buy,int quantity,std::size_t base,const std::string& selectedPartner){
 if(quantity<1||quantity>100)return {false,"Select 1–100 units"};double now=state["hours"];if(!tradeAirport(base,now))return {false,"Trade requires completed storage and airport at the selected base"};std::string partner=selectedPartner.empty()?constants["tradePartners"].value("default",std::string("Germany")):selectedPartner;double duration=tradeFlightHours(partner,base);if(duration<=0)return {false,"Select a valid trading country"};
 const auto* item=record(group,id);long long price=0;if(item){price=item->value("production",Json::object()).value("marketPrice",0LL);if(item->value("availableAfterDays",0)>now/24)return {false,"Item is not yet available"};auto research=item->value("requiresResearch",std::string(""));if(!research.empty()&&state["research"].value(research,0.)<1)return {false,"Required research is incomplete"};}else if(group=="materials"&&(id=="iron"||id=="plastics"||id=="electronics"||id=="glass"))price=id=="electronics"?200:50;
 if(price<=0)return {false,"Item is not tradeable"};int count=state["stock"].value(id,0);long long money=state["money"],value=(buy?price:price/2)*quantity;if(buy&&money<value)return {false,"Insufficient funds"};if(!buy&&count<quantity)return {false,"Insufficient stock"};if(state.contains("tradeFlights")&&state["tradeFlights"].size()>=4096)return {false,"Too many cargo flights"};
 if(!state.contains("tradeFlights"))state["tradeFlights"]=Json::array();auto& flights=state["tradeFlights"];while(flights.size()>256&&flights[0]["delivered"].get<bool>())flights.erase(0);if(buy)state["money"]=money-value;else state["stock"][id]=count-quantity;flights.push_back({{"group",group},{"id",id},{"quantity",quantity},{"buy",buy},{"base",base},{"partner",partner},{"departed",now},{"arrival",now+duration},{"value",value},{"delivered",false},{"status","inFlight"},{"hull",100.}});return {true,buy?"Purchase booked; cargo arrives by aircraft":"Sale dispatched; payment follows aircraft delivery"};
}
void Engine::processFreight(double now){if(!state.contains("tradeFlights"))return;for(auto& flight:state["tradeFlights"]){if(flight["delivered"].get<bool>()||flight["status"]=="destroyed"||flight["arrival"].get<double>()>now)continue;std::string id=flight["id"];int quantity=flight["quantity"];if(flight["buy"].get<bool>()){std::size_t base=flight["base"];if(!tradeAirport(base,now)){flight["status"]="awaitingAirport";continue;}auto capacity=storageCapacity();bool uranium=id=="uranium";double used=capacity[uranium?"uraniumUsed":"used"],maximum=capacity[uranium?"uraniumCapacity":"capacity"],incoming=storageUnitLitres(id)*quantity/1200.;if(used+incoming>maximum+1e-8){flight["status"]="awaitingStorage";continue;}state["stock"][id]=state["stock"].value(id,0)+quantity;}else state["money"]=state["money"].get<long long>()+flight["value"].get<long long>();flight["delivered"]=true;flight["status"]="delivered";log("CARGO FLIGHT DELIVERED: "+id+" · "+flight["partner"].get<std::string>());}}
Json Engine::freightStatus(std::size_t index,double at)const{if(!state.contains("tradeFlights")||index>=state["tradeFlights"].size())return nullptr;auto flight=state["tradeFlights"][index];auto base=state["bases"][flight["base"].get<std::size_t>()];Json partner;for(const auto& p:tradePartners())if(p["id"]==flight["partner"]){partner=p;break;}if(at<0)at=state["hours"];if(flight["status"]=="destroyed")at=flight["lostAt"];double start=flight["departed"],end=flight["arrival"],fraction=std::clamp((at-start)/(end-start),0.,1.);Json from=flight["buy"].get<bool>()?partner:base,to=flight["buy"].get<bool>()?base:partner;double lon0=from["lon"],lat0=from["lat"],lon1=to["lon"],lat1=to["lat"];flight["lon"]=std::remainder(lon0+std::remainder(lon1-lon0,360.)*fraction,360.);flight["lat"]=lat0+(lat1-lat0)*fraction;flight["progress"]=fraction;flight["hoursLeft"]=std::max(0.,end-state["hours"].get<double>());return flight;}
Result Engine::damageFreight(std::size_t index,double damage,const std::string& source,double at){if(!state.contains("tradeFlights")||index>=state["tradeFlights"].size()||!std::isfinite(damage)||damage<=0)return {false,"Invalid cargo aircraft damage"};auto& f=state["tradeFlights"][index];if(f["delivered"].get<bool>()||f["status"]=="destroyed")return {false,"Cargo flight is no longer active"};if(at<0)at=state["hours"];double hull=std::max(0.,f.value("hull",100.)-damage);f["hull"]=hull;if(hull<=0){f["status"]="destroyed";f["lostAt"]=at;f["lostBy"]=source;log("CARGO AIRCRAFT DESTROYED · NO REFUND");return {true,"Cargo aircraft destroyed; cargo lost without compensation"};}return {true,"Cargo aircraft damaged"};}
void Engine::processFreightThreats(double old,double now){if(!state.contains("tradeFlights"))return;constexpr double step=.25;for(std::size_t i=0;i<state["tradeFlights"].size();++i){auto& f=state["tradeFlights"][i];if(f["delivered"].get<bool>()||f["status"]=="destroyed")continue;double end=(f["status"]=="awaitingAirport"||f["status"]=="awaitingStorage")?now:std::min(now,f["arrival"].get<double>()),at=f.value("threatThrough",f["departed"].get<double>())+step;if(at<old)at=old;for(;at<=end+1e-8;at+=step){auto position=freightStatus(i,at);f["threatThrough"]=at;for(const auto& u:state["ufos"]){double born=u.value("spawned",std::max(0.,u.value("expires",720.)-720.));if(at<born||at>=u["expires"].get<double>()||ufoEnvironmentAt(u,at)!="AIR"||distance(position["lat"],position["lon"],u["lat"],u["lon"])>350)continue;if(rng()%100<40)damageFreight(i,35+int(rng()%31),"UFO",at);if(f["status"]=="destroyed")break;}if(f["status"]=="destroyed")break;}}}
bool Engine::validFreight(const Json& campaign)const{try{if(!campaign.contains("tradeFlights"))return true;const auto& flights=campaign["tradeFlights"];if(!flights.is_array()||flights.size()>4096)return false;for(const auto& f:flights){if(!f.is_object()||!f.at("buy").is_boolean()||!f.at("delivered").is_boolean()||!f.at("quantity").is_number_integer()||!f.at("base").is_number_integer()||!f.at("value").is_number_integer())return false;int qty=f["quantity"];long long bi=f["base"],value=f["value"];double departed=f.at("departed"),arrival=f.at("arrival");std::string partner=f.at("partner"),group=f.at("group"),id=f.at("id"),status=f.at("status");if(qty<1||qty>100||bi<0||bi>=static_cast<long long>(campaign["bases"].size())||value<0||!std::isfinite(departed)||!std::isfinite(arrival)||departed<0||departed>campaign["hours"].get<double>()||arrival<=departed)return false;bool known=false;for(const auto& p:tradePartners())if(p["id"]==partner)known=true;if(!known||(!record(group,id)&&!(group=="materials"&&(id=="iron"||id=="plastics"||id=="electronics"||id=="glass"))))return false;if(status!="inFlight"&&status!="awaitingAirport"&&status!="awaitingStorage"&&status!="delivered"&&status!="destroyed")return false;if(f.contains("hull")&&(!f["hull"].is_number()||!std::isfinite(f["hull"].get<double>())||f["hull"].get<double>()<0||f["hull"].get<double>()>100))return false;if(status=="destroyed"&&(!f.contains("hull")||f["hull"].get<double>()!=0||!f.contains("lostAt")||!f["lostAt"].is_number()||!std::isfinite(f["lostAt"].get<double>())||f["lostAt"].get<double>()<departed||f["lostAt"].get<double>()>campaign["hours"].get<double>()))return false;if(f.contains("threatThrough")&&(!f["threatThrough"].is_number()||!std::isfinite(f["threatThrough"].get<double>())||f["threatThrough"].get<double>()<departed||f["threatThrough"].get<double>()>campaign["hours"].get<double>()+1e-8))return false;if(f["delivered"].get<bool>()!=(status=="delivered")||(f["delivered"].get<bool>()&&arrival>campaign["hours"].get<double>()))return false;}return true;}catch(...){return false;}}
}
